begin; update public.roadmaps set costs='[]'::jsonb, next_steps=jsonb_set(next_steps,'{presentation}',coalesce(next_steps->'presentation','{}'::jsonb) || '{"infrastructure_title": "As propostas e o escopo aprovado.", "scope_options": [{"label": "A · Portal moderno", "selected": false, "features": ["Portal responsivo, editorias e capa organizada por seções.", "Painel básico da redação e 2 modelos: notícia padrão e coluna/opinião.", "Sindicato e jornal de bairro em abas com visual próprio.", "Espaços fixos para anúncios e otimização para Google e Google Notícias.", "Suporte pós-entrega: 30 dias. Prazo estimado na proposta: 4–6 semanas."]}, {"label": "B · Portal + comunidade", "selected": true, "features": ["Toda a base da opção A, com painel editorial completo.", "4 modelos: notícia padrão, coluna/opinião, foto-reportagem e reportagem especial.", "Duas seções com capa, identidade e anúncios próprios, publicadas pela equipe Gazeta em um painel único.", "Cadastro de leitores, área personalizada e newsletter por e-mail.", "Base preparada para assinatura futura e avisos de notícias no navegador.", "Suporte pós-entrega: 60 dias. Prazo estimado na proposta: 7–9 semanas."]}, {"label": "C · Ecossistema completo", "selected": false, "features": ["Tudo da opção B, mais aplicativo instalável no celular (iPhone e Android).", "Sistema completo de anúncios e relatórios de audiência, anúncios e assinantes.", "Todos os modelos de conteúdo, incluindo cobertura ao vivo, vídeo e personalizados.", "Avisos de notícias no navegador e no celular.", "Suporte pós-entrega: 90 dias. Prazo estimado na proposta: 10–12 semanas."]}], "scope_note": "Opção B aprovada. A operação contempla hospedagem, banco de dados, manutenção e suporte a partir da entrega. Aplicativo nativo nas lojas App Store e Google Play é uma etapa futura opcional. Os prazos acima são as estimativas da proposta, não novas datas de entrega."}'::jsonb) where project_id='fa681812-5c4a-4868-bf9d-699442ec7c52'; commit;